def load() -> pd.DataFrame:
    import pandas as pd, glob
    paths = glob.glob('data/environment/input/monthly_precipitations_*.csv')
    out=[]
    for p in sorted(paths):
        df=pd.read_csv(p)
        df['source']=p.split('/')[-1]
        out.append(pd.concat([df.head(2), df.tail(2)]))
    return pd.concat(out, ignore_index=True)

