def load() -> pd.DataFrame:
    import pandas as pd, glob, os
    files = glob.glob('data/environment/input/monthly_precipitations_*.csv')
    dfs = []
    for fp in files:
        df = pd.read_csv(fp)
        df['source'] = os.path.basename(fp)
        dfs.append(df)
    return pd.concat(dfs, ignore_index=True)
